window.RTLBenchLSData.register("assets/d334edb770bfbdbb4a2f52d6e60690981e511245b0d07e38646f37a135d95fe8.txt","module autovcoder_091131 (  /*AUTOARG*/\n    // Outputs\n    phy2cs_data,\n    phy2cs_k,\n    txdata_fis,\n    tx_charisk_fis,\n    // Inputs\n    clk_75m,\n    host_rst,\n    cs2phy_data,\n    link_up,\n    fsm2phy_k,\n    rxdata_fis,\n    rxcharisk\n);\n  //phy if system signal\n  input clk_75m;  //75M\n  input host_rst;\n\n  //32 bit and 75M clock domain\n  input [31:0] cs2phy_data;\n  output reg [31:0] phy2cs_data;\n  input link_up;\n  output reg phy2cs_k;\n  input fsm2phy_k;\n\n  //32 bit and 75M clock domain\n  input [31:0] rxdata_fis;\n  input [3:0] rxcharisk;\n  output [31:0] txdata_fis;\n  output tx_charisk_fis;\n\n  reg [31:0] rx_data_link_tmp;\n  reg        phy_sync_0001;\n  reg        phy_sync_0010;\n  reg        phy_sync_0100;\n  reg        phy_sync_1000;\n\n  assign txdata_fis = cs2phy_data;\n  assign tx_charisk_fis = fsm2phy_k;\n\n  always @(posedge clk_75m)\n    if (host_rst) begin\n      phy2cs_data <= 32'hb5b5_957c;\n      phy_sync_0001 <= 0;\n      phy_sync_0010 <= 0;\n      phy_sync_0100 <= 0;\n      phy_sync_1000 <= 0;\n      rx_data_link_tmp <= 0;\n    end else if (~link_up) begin\n      phy2cs_data <= 32'hb5b5_957c;\n      phy_sync_0001 <= 0;\n      phy_sync_0010 <= 0;\n      phy_sync_0100 <= 0;\n      phy_sync_1000 <= 0;\n      rx_data_link_tmp <= 0;\n    end else begin\n      if (rxcharisk == 4'b0001 | phy_sync_0001) begin\n        phy2cs_data   <= rxdata_fis;\n        phy_sync_0001 <= 1;\n      end else if (rxcharisk == 4'b0010 | phy_sync_0010) begin\n        rx_data_link_tmp <= rxdata_fis;\n        phy2cs_data      <= {rxdata_fis[7:0], rx_data_link_tmp[31:8]};\n        phy_sync_0010    <= 1;\n      end else if (rxcharisk == 4'b0100 | phy_sync_0100) begin\n        rx_data_link_tmp <= rxdata_fis;\n        phy2cs_data      <= {rxdata_fis[15:0], rx_data_link_tmp[31:16]};\n        phy_sync_0100    <= 1;\n      end else if (rxcharisk == 4'b1000 | phy_sync_1000) begin\n        rx_data_link_tmp <= rxdata_fis;\n        phy2cs_data      <= {rxdata_fis[23:0], rx_data_link_tmp[31:24]};\n        phy_sync_1000    <= 1;\n      end\n    end\n\n  reg rx_k_tmp;\n\n  always @(posedge clk_75m)  //for lost primitive 3737b57c\n    if (~link_up) begin\n      rx_k_tmp <= 0;\n    end else if (rxcharisk[1] | rxcharisk[2] | rxcharisk[3]) begin\n      rx_k_tmp <= 1;\n    end else begin\n      rx_k_tmp <= 0;\n    end\n\n  always @(posedge clk_75m)\n    if (~link_up) begin\n      phy2cs_k <= 0;\n    end else if (rxcharisk[0]) begin\n      phy2cs_k <= 1;\n    end else begin\n      phy2cs_k <= rx_k_tmp;\n    end\n\nendmodule\n\n");
